questionvariables.text:
/* helpers: relation tokens, display strings, inequality builders */
relt(r) := if r="lt" then "\\lt" else if r="le" then "\\le" else if r="gt" then "\\gt" else "\\ge";
reluc(r) := if r="lt" then "<" else if r="le" then "≤" else if r="gt" then ">" else "≥";
relflip(r) := if r="lt" then "gt" else if r="le" then "ge" else if r="gt" then "lt" else "le";
relother(r) := if r="lt" then "le" else if r="le" then "lt" else if r="gt" then "ge" else "gt";
relcomp(r) := if r="lt" then "ge" else if r="le" then "gt" else if r="gt" then "le" else "lt";
strictp(r) := is(r="lt" or r="gt");
/* Typed answers must be one inequality; "and"/"or" statements are rejected at validation. */
vsingle(ex) := if not atom(ex) and member(op(ex), ["and", "or", "nounand", "nounor"]) then "Type a single inequality, without the words and or or." else "";
mkin(u, r, w) := if r="lt" then u<w else if r="le" then u<=w else if r="gt" then u>w else u>=w;
holds(u, r, w) := if r="lt" then is(u<w) else if r="le" then is(u<=w) else if r="gt" then is(u>w) else is(u>=w);
relopts(c) := [["lt",is(c="lt"),"<"],["le",is(c="le"),"≤"],["gt",is(c="gt"),">"],["ge",is(c="ge"),"≥"]];
termp(v) := block([dd], dd: denom(v), while is(mod(dd,2)=0) do dd: dd/2, while is(mod(dd,5)=0) do dd: dd/5, is(dd=1));
nd(v) := if integerp(v) then string(v) else if termp(v) then string(float(v))
  else sconcat(if is(v<0) then "-" else "", "\\frac{", string(abs(num(v))), "}{", string(denom(v)), "}");
ndm(v) := sconcat("\\(", nd(v), "\\)");
/* plain-text number for aria-labels (nd gives TeX fractions, which a screen reader reads raw) */
ndt(v) := if integerp(v) then string(v) else if termp(v) then string(float(v)) else sconcat(string(num(v)), "/", string(denom(v)));
trm(k, v, fst) := block([m, s], m: abs(k), s: if v="" then nd(m) else if m=1 then v else sconcat(nd(m), v),
  if fst then (if k<0 then sconcat("-", s) else s) else (if k<0 then sconcat(" - ", s) else sconcat(" + ", s)));
lfs(L) := block([s, t], s: "", for t in L do (if t[1]#0 then s: sconcat(s, trm(t[1], t[2], is(s="")))), if s="" then "0" else s);
ins(a, b, c, r) := sconcat(lfs([[a,"x"],[b,"y"]]), " ", relt(r), " ", nd(c));
ineqd(a, b, c, r) := sconcat("\\(", ins(a, b, c, r), "\\)");
lind(a, b, c) := sconcat("\\(", lfs([[a,"x"],[b,"y"]]), " = ", nd(c), "\\)");
ineqm(a, b, c, r) := mkin(a*x+b*y, r, c);
/* region helpers: corners of the triangle cut out by three lines, centroid */
meet(L1, L2) := block([d], d: L1[1]*L2[2]-L2[1]*L1[2], [(L1[3]*L2[2]-L2[3]*L1[2])/d, (L1[1]*L2[3]-L2[1]*L1[3])/d]);
ptd(P) := sconcat("(", ndt(P[1]), ", ", ndt(P[2]), ")");
/* system helpers: S is [[a,b,c,rel] x 3] */
sd(S) := makelist(ineqd(S[j][1], S[j][2], S[j][3], S[j][4]), j, 1, 3);
spl(L) := sconcat(lfs([[L[1],"x"],[L[2],"y"]]), " = ", ndt(L[3]), if strictp(L[4]) then " (dashed)" else " (solid)");
sall(S) := sconcat(sd(S)[1], ", ", sd(S)[2], " and ", sd(S)[3]);
/* Design: which lettered region satisfies the inequalities (no shading). Source: adapted from SMP GCSE Higher 2, Chapter 1, questions B5(a) and D1(a).
   q41 [[3 inequalities], [[letter, label x, label y, fails flags]], letter of R]; R never A;
   every entry has a region failing exactly one inequality and one failing two or more. */
q41: [[[[1,0,5,"le"],[0,1,-1,"gt"],[-7,3,-21,"le"]],[["A",1,5,[0,0,1]],["B",-1.5,-2.5,[0,1,1]],["C",4,0.5,[0,0,0]],["D",3.5,-2.5,[0,1,0]],["E",7.5,4,[1,0,0]],["F",6,9.5,[1,0,1]],["G",7.5,-2.5,[1,1,0]]],"C"],[[[1,0,2,"ge"],[0,1,0,"gt"],[7,4,28,"le"]],[["A",6,5,[0,0,1]],["B",2.5,1,[0,0,0]],["C",3.5,-2,[0,1,0]],["D",-1.5,-1.5,[1,1,0]],["E",7.5,-1.5,[0,1,1]],["F",1,8,[1,0,1]],["G",-1.5,4,[1,0,0]]],"B"],[[[1,0,0,"gt"],[0,1,1,"ge"],[6,5,30,"lt"]],[["A",-1.5,-1.5,[1,1,0]],["B",5.5,6,[0,0,1]],["C",1.5,2.5,[0,0,0]],["D",-1.5,9.5,[1,0,1]],["E",3,-1.5,[0,1,0]],["F",8,-1.5,[0,1,1]],["G",-1.5,4.5,[1,0,0]]],"C"],[[[1,0,4,"lt"],[0,1,6,"le"],[7,8,56,"ge"]],[["A",-2.5,7.5,[0,1,1]],["B",7.5,3,[1,0,0]],["C",1,1.5,[0,0,1]],["D",3,5.5,[0,0,0]],["E",6.5,-1.5,[1,0,1]],["F",7,8,[1,1,0]],["G",1.5,8.5,[0,1,0]]],"D"],[[[1,0,3,"gt"],[0,1,0,"ge"],[8,7,56,"le"]],[["A",5.5,-1.5,[0,1,0]],["B",4,1.5,[0,0,0]],["C",1,-1.5,[1,1,0]],["D",-1.5,4,[1,0,0]],["E",1.5,8.5,[1,0,1]],["F",9.5,-1,[0,1,1]],["G",7,5.5,[0,0,1]]],"B"],[[[1,0,0,"gt"],[0,1,-2,"gt"],[7,5,35,"lt"]],[["A",6,5,[0,0,1]],["B",-1,9.5,[1,0,1]],["C",-1.5,3.5,[1,0,0]],["D",8.5,-2.5,[0,1,1]],["E",2,1,[0,0,0]],["F",-1.5,-2.5,[1,1,0]],["G",3.5,-2.5,[0,1,0]]],"E"],[[[1,0,6,"lt"],[0,1,-1,"ge"],[-7,4,-28,"le"]],[["A",4.5,-2.5,[0,1,0]],["B",8.5,3,[1,0,0]],["C",1.5,4.5,[0,0,1]],["D",7.5,8.5,[1,0,1]],["E",8,-2.5,[1,1,0]],["F",1,-2.5,[0,1,1]],["G",5,0.5,[0,0,0]]],"G"],[[[1,0,-2,"gt"],[0,1,6,"lt"],[-4,7,28,"gt"]],[["A",-2.5,8,[1,1,0]],["B",8.5,7.5,[0,1,1]],["C",2.5,8.5,[0,1,0]],["D",-2.5,-0.5,[1,0,1]],["E",4.5,1,[0,0,1]],["F",-1,5,[0,0,0]],["G",-2.5,4.5,[1,0,0]]],"F"],[[[1,0,1,"gt"],[0,1,1,"ge"],[8,3,24,"le"]],[["A",2.5,-2,[0,1,0]],["B",-1.5,-1.5,[1,1,0]],["C",0.5,8.5,[1,0,1]],["D",6.5,-1.5,[0,1,1]],["E",5.5,5.5,[0,0,1]],["F",-1.5,5,[1,0,0]],["G",1.5,2.5,[0,0,0]]],"G"],[[[1,0,5,"le"],[0,1,-1,"gt"],[-8,3,-24,"lt"]],[["A",7.5,-2.5,[1,1,0]],["B",1,5,[0,0,1]],["C",7.5,4,[1,0,0]],["D",5.5,8.5,[1,0,1]],["E",4,0.5,[0,0,0]],["F",3.5,-2.5,[0,1,0]],["G",-1.5,-2.5,[0,1,1]]],"E"]];
ix: 1+rand(10);
S: q41[ix][1]; regs: q41[ix][2]; Rl: q41[ix][3];
lab: makelist([regs[j][1], regs[j][2], regs[j][3]], j, 1, 7);
ds: sd(S);
nf: makelist(apply("+", regs[j][4]), j, 1, 7);
one1: regs[first(sublist(makelist(j, j, 1, 7), lambda([j], is(nf[j]=1))))][1];
two1: regs[first(sublist(makelist(j, j, 1, 7), lambda([j], is(nf[j]>=2))))][1];
o1: makelist([L, is(L=Rl), L], L, ["A","B","C","D","E","F","G"]);
Rj: first(sublist(makelist(j, j, 1, 7), lambda([j], is(regs[j][1]=Rl))));
arl: sconcat("Three lines on a grid from -3 to 10: ", spl(S[1]), ", ", spl(S[2]), " and ", spl(S[3]),
  ". They divide the grid into regions labelled ", simplode(makelist(sconcat(regs[j][1], " at (", string(regs[j][2]), ", ", string(regs[j][3]), ")"), j, 1, 7), ", "), ".");

feedbackvariables.text:
cj: first(sublist(makelist(j, j, 1, 7), lambda([j], is(regs[j][1]=ans1))));
nfail: nf[cj];
fl: sublist(makelist(j, j, 1, 3), lambda([j], is(regs[cj][4][j]=1)));
fstr: simplode(makelist(ds[j], j, fl), " and ");
